import itertools, time
from submissions.solve import load_data, audit_solution, solve_scenario_greedy, build_solution

data=load_data()
base_fs={
 'open_shelters':['S1','S2','S3','S5'],
 'active_corridors':['C1','C2','C3','C4','C5'],
 'staging': {'B01':'D3','B02':'D3','B03':'D2','B04':'D2','B05':'D2','B06':'D3','B07':'D3','B08':'D2','B09':'D1','B10':'D1'}
}

def eval_fs(fs):
    sr={sid: solve_scenario_greedy(data,sid,fs) for sid in sorted(data['scenarios'])}
    sol=build_solution(data,fs,sr)
    audit=audit_solution(data,sol)
    return audit,sol

base_audit,_=eval_fs(base_fs)
print('base', base_audit['total_cost'])

shelters=sorted(data['shelters'])
corridors=sorted(data['corridors'])
backup={s:data['shelters'][s]['backup_power'] for s in shelters}
smoke={s:data['shelters'][s]['smoke_safe_rating'] for s in shelters}
start=time.time(); best=(base_audit['total_cost'], None); count=0
for r in range(1,5):
    for open_set in itertools.combinations(shelters,r):
        open_set=set(open_set)
        if sum(backup[s] for s in open_set) < data['config']['min_backup_power_shelters']:
            continue
        # must allow all medical assignments and severe-smoke usable set not empty enough, leave audit to fail if not.
        for mask in range(1<<len(corridors)):
            active=[corridors[i] for i in range(len(corridors)) if (mask>>i)&1]
            if len(active) > data['config']['max_active_corridors']:
                continue
            fs={'open_shelters':sorted(open_set),'active_corridors':active,'staging':dict(base_fs['staging'])}
            count+=1
            audit,_=eval_fs(fs)
            if audit['errors']:
                continue
            if audit['total_cost'] < best[0] - 1e-8:
                best=(audit['total_cost'], (tuple(sorted(open_set)), tuple(active)))
                print('improve', best, 'elapsed', time.time()-start)
print('count', count, 'best', best, 'elapsed', time.time()-start)
